# -*- coding: utf-8 -*-\n\"\"\"\nRE7_VALIDAR_RUTEO_RE-P-068_v01.py\nValidacion RE-P-068: compara conduits creados en Revit contra los 147 tramos de\nreferencia de V02-f (conduits_v01.json).\n\nLee:\n  - data/f7_conduits_creados_v01.json          (salida de RE7_CREAR_CONDUITS_v01.py)\n  - data/f7_conduits_ref_v02f_v01.json         (salida de RE7_CREAR_CONDUITS_REFERENCIA_V02F_v01.py)\n  - data/f7_conduits_desde_revit_v01.json      (salida de RE7_EXPORTAR_CONDUITS_REVIT_v01.py)\n  - datos de referencia V02-f: .claude/worktrees/conduit-parser/data/v02f/conduits_v01.json\n\nEscribe:\n  - data/f7_validacion_re-p-068_v01.json\n\nUso (Python 3.12 externo, no Revit):\n    python RE7_VALIDAR_RUTEO_RE-P-068_v01.py\n\"\"\"\nimport datetime\nimport json\nimport math\nimport os\nimport sys\n\ntry:\n    from pathlib import Path\nexcept Exception:\n    pass\n\nFT_A_MM = 304.8\nDIST_MATCH_TOLERANCIA_MM = 200.0   # tolerancia para considerar un tramo \"coincidente\"\nLONG_TOLERANCIA_MM = 50.0          # tolerancia en longitud\n\n\ndef raiz_proyecto():\n    raiz = os.environ.get(\"REVITELECTRICO_ROOT\", \"\").strip()\n    if raiz and os.path.exists(raiz):\n        return raiz\n    return r\"D:\\Work\\PROJECTS\RevitElectrico\"\n\n\ndef cargar_json(path):\n    if not os.path.exists(path):\n        return None\n    with open(path, \"r\", encoding=\"utf-8\") as f:\n        return json.load(f)\n\n\ndef guardar_json(path, datos):\n    contenido = json.dumps(datos, ensure_ascii=True, indent=2)\n    with open(path, \"w\", encoding=\"utf-8\") as f:\n        f.write(contenido)\n\n\ndef punto_a_mm(p):\n    return [float(p[0]), float(p[1]), float(p[2])]\n\n\ndef distancia_puntos(p, q):\n    return math.sqrt((p[0]-q[0])**2 + (p[1]-q[1])**2 + (p[2]-q[2])**2)\n\n\ndef normalizar_tramo(a_mm, b_mm):\n    \"\"\"Devuelve el tramo con extremos ordenados (para comparar sin importar direccion).\"\"\"\n    return tuple(sorted([tuple(a_mm), tuple(b_mm)]))\n\n\ndef tramo_longitud(a_mm, b_mm):\n    return distancia_puntos(a_mm, b_mm)\n\n\ndef obtener_coords_creado(c):\n    \"\"\"Extrae a_mm y b_mm de un conduit creado, aceptando varios formatos de campo.\"\"\"\n    a = c.get(\"a_mm_real\") or c.get(\"a_mm\")\n    b = c.get(\"b_mm_real\") or c.get(\"b_mm\")\n    if a is not None:\n        a = punto_a_mm(a)\n    if b is not None:\n        b = punto_a_mm(b)\n    return a, b\n\n\ndef obtener_id_creado(c):\n    \"\"\"Extrae el id de un conduit creado, aceptando varios formatos.\"\"\"\n    return c.get(\"conduit_id\") or c.get(\"id_ref\") or c.get(\"id_script\")\n\n\ndef obtener_verificado(c):\n    \"\"\"Extrae el estado de verificacion, default True si no hay.\"\"\"\n    v = c.get(\"verificado\")\n    if v is None:\n        v = c.get(\"verificado_creacion\")\n    return bool(v) if v is not None else True\n\n\ndef encontrar_mejor_coincidencia(tramo_creado, tramos_referencia):\n    \"\"\"Busca el tramo de referencia mas cercano por distancia de extremos.\"\"\"\n    a_creado = tramo_creado[\"a_mm\"]\n    b_creado = tramo_creado[\"b_mm\"]\n    if a_creado is None or b_creado is None:\n        return None, None\n\n    mejor_ref = None\n    mejor_score = None\n    mejor_dist_endpoints = None\n\n    for ref in tramos_referencia:\n        a_ref = ref[\"a_mm\"]\n        b_ref = ref[\"b_mm\"]\n        # Probar ambas direcciones\n        d1 = distancia_puntos(a_creado, a_ref) + distancia_puntos(b_creado, b_ref)\n        d2 = distancia_puntos(a_creado, b_ref) + distancia_puntos(b_creado, a_ref)\n        dist_endpoints = min(d1, d2)\n\n        score = dist_endpoints\n        if mejor_score is None or score < mejor_score:\n            mejor_score = score\n            mejor_ref = ref\n            mejor_dist_endpoints = dist_endpoints\n\n    return mejor_ref, mejor_dist_endpoints\n\n\ndef main():\n    raiz = raiz_proyecto()\n    print(\"=\" * 60)\n    print(\"RE7_VALIDAR_RUTEO_RE-P-068_v01 - Validacion contra V02-f\")\n    print(\"ejecutado_utc={}\".format(datetime.datetime.utcnow().strftime(\"%Y-%m-%d %H:%M:%S\")))\n    print(\"=\" * 60)\n\n    # Cargar conduits creados (probar 3 posibles archivos)\n    creado_paths = [\n        os.path.join(raiz, \"data\", \"f7_conduits_creados_v01.json\"),\n        os.path.join(raiz, \"data\", \"f7_conduits_ref_v02f_v01.json\"),\n        os.path.join(raiz, \"data\", \"f7_conduits_desde_revit_v01.json\"),\n    ]\n    conduits_creados = []\n    creado_path_usado = None\n    for cp in creado_paths:\n        datos_creados = cargar_json(cp)\n        if datos_creados is not None:\n            conduits_creados = datos_creados.get(\"conduits\", [])\n            creado_path_usado = cp\n            print(\"Conduits creados cargados desde: {} ({} items)\".format(cp, len(conduits_creados)))\n            break\n\n    if creado_path_usado is None:\n        print(\"ERROR: no se encontro ningun archivo de conduits creados.\")\n        print(\"     Ejecute primero un script de creacion o exportacion en Revit.\")\n        return 1\n\n    # Cargar referencia V02-f\n    ref_path = os.path.join(raiz, \".claude\", \"worktrees\", \"conduit-parser\", \"data\", \"v02f\", \"conduits_v01.json\")\n    datos_ref = cargar_json(ref_path)\n    if datos_ref is None:\n        print(\"ERROR: no existe {}\".format(ref_path))\n        return 1\n\n    tramos_ref = datos_ref if isinstance(datos_ref, list) else datos_ref.get(\"tramos\", [])\n    print(\"Tramos de referencia V02-f: {}\".format(len(tramos_ref)))\n\n    # Normalizar tramos de referencia para acceso rapido\n    ref_list = []\n    for t in tramos_ref:\n        a = punto_a_mm(t[\"a\"])\n        b = punto_a_mm(t[\"b\"])\n        ref_list.append({\n            \"id\": t.get(\"id\"),\n            \"tipo\": t.get(\"tipo\", \"\"),\n            \"nivel\": t.get(\"nivel\", \"\"),\n            \"diam_mm\": t.get(\"diam_mm\", 0),\n            \"servicio\": t.get(\"servicio\", \"\"),\n            \"a_mm\": a,\n            \"b_mm\": b,\n            \"longitud_mm\": tramo_longitud(a, b),\n            \"clave\": normalizar_tramo(a, b),\n        })\n    ref_por_clave = {r[\"clave\"]: r for r in ref_list}\n    ref_por_id = {r[\"id\"]: r for r in ref_list}\n\n    # Validar cada conduit creado\n    resultados = []\n    coincididas_ids = set()\n    coincidencias_exactas = 0\n    coincidencias_proximas = 0\n    sin_coincidencia = 0\n\n    for c in conduits_creados:\n        creado_id = obtener_id_creado(c)\n        a_real, b_real = obtener_coords_creado(c)\n        largo_real = c.get(\"largo_real_mm\") or c.get(\"largo_mm\")\n        verificado = obtener_verificado(c)\n        diametro = c.get(\"diametro_mm\") or c.get(\"diametro_creado_mm\")\n        servicio = c.get(\"servicio\") or c.get(\"servicio_creado\")\n\n        # Buscar coincidencia: primero por id_ref, luego por coordenadas\n        ref = None\n        dist_endpoints = None\n        id_ref_directo = c.get(\"id_ref\")\n        if id_ref_directo is not None and id_ref_directo in ref_por_id:\n            ref = ref_por_id[id_ref_directo]\n            coincididas_ids.add(ref[\"id\"])\n            if a_real is not None and b_real is not None and ref.get(\"a_mm\") and ref.get(\"b_mm\"):\n                d1 = distancia_puntos(a_real, ref[\"a_mm\"]) + distancia_puntos(b_real, ref[\"b_mm\"])\n                d2 = distancia_puntos(a_real, ref[\"b_mm\"]) + distancia_puntos(b_real, ref[\"a_mm\"])\n                dist_endpoints = min(d1, d2)\n        elif a_real is not None and b_real is not None:\n            ref, dist_endpoints = encontrar_mejor_coincidencia({\"a_mm\": a_real, \"b_mm\": b_real}, ref_list)\n            if ref is not None:\n                coincididas_ids.add(ref[\"id\"])\n\n        entrada = {\n            \"conduit_id_creado\": creado_id,\n            \"id_ref\": ref[\"id\"] if ref else None,\n            \"ref_tipo\": ref[\"tipo\"] if ref else None,\n            \"ref_servicio\": ref[\"servicio\"] if ref else None,\n            \"ref_diam_mm\": ref[\"diam_mm\"] if ref else None,\n            \"dist_endpoints_mm\": round(dist_endpoints, 2) if dist_endpoints is not None else None,\n            \"verificado_creacion\": verificado,\n            \"largo_creado_mm\": largo_real,\n            \"diametro_creado_mm\": diametro,\n            \"servicio_creado\": servicio,\n            \"clave_match_exacto\": None,\n        }\n\n        if ref is not None:\n            clave_creado = normalizar_tramo(a_real, b_real) if (a_real and b_real) else None\n            if clave_creado is not None:\n                es_exacto = (clave_creado == ref[\"clave\"])\n                entrada[\"clave_match_exacto\"] = es_exacto\n                if es_exacto:\n                    coincidencias_exactas += 1\n                elif dist_endpoints is not None and dist_endpoints <= DIST_MATCH_TOLERANCIA_MM:\n                    coincidencias_proximas += 1\n                else:\n                    sin_coincidencia += 1\n            else:\n                sin_coincidencia += 1\n        else:\n            sin_coincidencia += 1\n\n        resultados.append(entrada)\n\n    # Resumen\n    total_creados = len(conduits_creados)\n    total_ref = len(ref_list)\n    total_coincididas = len(coincididas_ids)\n    no_coincidadas_ref = [r for r in ref_list if r[\"id\"] not in coincididas_ids]\n\n    reporte = {\n        \"version\": \"v01\",\n        \"script\": \"RE7_VALIDAR_RUTEO_RE-P-068_v01\",\n        \"generado_utc\": datetime.datetime.utcnow().strftime(\"%Y-%m-%d %H:%M:%S\"),\n        \"parametros\": {\n            \"tolerancia_coincidencia_mm\": DIST_MATCH_TOLERANCIA_MM,\n            \"tolerancia_longitud_mm\": LONG_TOLERANCIA_MM,\n        },\n        \"fuentes\": {\n            \"conduits_creados\": creado_path_usado,\n            \"referencia_v02f\": ref_path,\n        },\n        \"resumen\": {\n            \"conduits_creados_total\": total_creados,\n            \"tramos_referencia_total\": total_ref,\n            \"coincidencias_exactas\": coincidencias_exactas,\n            \"coincidencias_proximas\": coincidencias_proximas,\n            \"sin_coincidencia_creados\": sin_coincidencia,\n            \"tramos_ref_coincididos_total\": total_coincididas,\n            \"tramos_ref_sin_coincidir\": len(no_coincidadas_ref),\n            \"cobertura_ref_porcentaje\": round(100.0 * total_coincididas / total_ref, 2) if total_ref else 0.0,\n        },\n        \"resultados\": resultados,\n        \"tramos_ref_sin_coincidir\": [\n            {\"id\": r[\"id\"], \"tipo\": r[\"tipo\"], \"servicio\": r[\"servicio\"],\n             \"diam_mm\": r[\"diam_mm\"], \"longitud_mm\": r[\"longitud_mm\"],\n             \"a_mm\": r[\"a_mm\"], \"b_mm\": r[\"b_mm\"]}\n            for r in no_coincidadas_ref\n        ],\n    }\n\n    out_path = os.path.join(raiz, \"data\", \"f7_validacion_re-p-068_v01.json\")\n    guardar_json(out_path, reporte)\n    print(\"Reporte guardado en: {}\".format(out_path))\n    print(\"\")\n    print(\"RESUMEN:\")\n    print(\"  Conduits creados: {}\".format(total_creados))\n    print(\"  Tramos referencia V02-f: {}\".format(total_ref))\n    print(\"  Coincidencias exactas: {}\".format(coincidencias_exactas))\n    print(\"  Coincidencias cercanas (<{}mm): {}\".format(DIST_MATCH_TOLERANCIA_MM, coincidencias_proximas))\n    print(\"  Creados sin coincidencia: {}\".format(sin_coincidencia))\n    print(\"  Tramos ref no coincididos: {}\".format(len(no_coincidadas_ref)))\n    print(\"  Cobertura referencia: {}%\".format(reporte[\"resumen\"][\"cobertura_ref_porcentaje\"]))\n    print(\"=\" * 60)\n    return 0\n\n\nif __name__ == \"__main__\":\n    try:\n        raise SystemExit(main())\n    except SystemExit:\n        raise\n    except Exception as e:\n        import traceback\n        traceback.print_exc()\n        raise SystemExit(1)\n